"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0965-08-16:0":{"b": ["Տարսոնը հանձնվեց Բյուզանդիային. Կիլիկիան անցավ բյուզանդական իշխանության տակ", "b05e9bd3"], "d": ["Մամեստիան (Մոպսուեստիա) 965 թ. հուլիսին, Տարսոնը մեկ ամիս անց՝ 965 թ. օգոստոսի 16-ին, մարդասիրական պայմաններով հանձնվեցին և դարձյալ դարձան քրիստոնեական քաղաք։ Այսպիսով Կիլիկիայի շրջանը միացվեց Բյուզանդիային։", "faeb461f"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0969-10-28:0":{"b": ["Անտիոքն անցավ Բյուզանդիայի ձեռքը", "ad0a5da3"], "d": ["Բյուզանդական բանակները Հյուսիսային Սիրիայում բազմաթիվ ամրոցներ և քաղաքներ վերցնելուց հետո Կիլիկիայից եկած Միքայել Բուրցեսը և Պետրոս Փոկասը 969 թ. հոկտեմբերի 28-ին գրավեցին Անտիոքը։ Քաղաքը մոտ 115 տարի եղավ Բյուզանդիայի հիմնական հենակետը Սիրիայում։", "38b840e3"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0971-04-13:0":{"b": ["Ցիմիսխեսը գրոհով վերցրեց Մեծ Պրեսլավը. Արևելյան Բուլղարիան միացվեց Բյուզանդիային", "07c84840"], "d": ["Հովհաննես Ցիմիսխեսը 971 թ. ապրիլի 12-ին մտավ Պրեսլավի հարթավայր. ապրիլի 13-ի երեկոյան Սվյատոսլավի մարդկանց պաշտպանած բուլղարական մայրաքաղաքն ընկավ։ Բորիս ցարը գերվեց, և բյուզանդական կառավարումը տարածվեց Թրակիայում և Արևելյան Բուլղարիայում։", "ae050b34"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0979-01-01:0":{"b": ["Ատրպատականն անցավ Ռավադյանների ձեռքը. Մուսաֆիրյանները քաշվեցին Թարում (979 կամ 980)", "b5b0e767"], "d": ["Ատրպատականն անցավ Ռավադյանների ձեռքը. Մուսաֆիրյանները քաշվեցին Թարում (979 կամ 980)", "b5b0e767"]},
